      padding: 0;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      background-color: #f0f0f0;
    }
    canvas {
      border: 1px solid #ccc;
    }
  </style>
</head>
<body>
  <script>
    let x = 0;

    function setup() {
      createCanvas(800, 400);
      strokeWeight(4);
      stroke(0);
      noFill();
    }

    function draw() {
      background(255); // White background

      // Update position
      x += 2;
      if (x > width + 50) {
        x = -50;
      }

      // Speed of animation based on frame count
      let t = frameCount * 0.15;

      push();
      translate(x, height / 2 + 20);

      // Head
      circle(0, -60, 30);

      // Body
      line(0, -45, 0, 10);

      // Arms
      let armAngle = sin(t) * PI / 3;
      // Right arm (back)
